func (s Profile) JSONSize() int {
	size := 49
	if s.Bio == nil {
		size += 4
	} else {
		size += 2
		size += len((*s.Bio)) * 2
	}
	if s.Image == nil {
		size += 4
	} else {
		size += 2
		size += len((*s.Image)) * 2
	}
	size += len(s.Username) * 2
	return size
}

func (s Profile) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"bio\":"...)
	if s.Bio == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = ggen.AppendStringNoHTML(dst, (*s.Bio))
	}
	dst = append(dst, ",\"following\":"...)
	dst = strconv.AppendBool(dst, s.Following)
	dst = append(dst, ",\"image\":"...)
	if s.Image == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = ggen.AppendStringNoHTML(dst, (*s.Image))
	}
	dst = append(dst, ",\"username\":\""...)
	dst = ggen.AppendStringNoHTML(dst, s.Username)
	return append(dst, '}'), nil
}

